firestore.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() {
      return request.auth != null;
    }
    function isAdmin() {
      return isAuthenticated() && (
        request.auth.uid == 'bi3c890VUXhVE0JFxroYfnlQwea2' ||
        (exists(/databases/$(database)/documents/users/$(request.auth.uid)) &&
         get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin')
      );
    }
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }
    match /users/{userId} {
      allow read: if isAdmin() || isOwner(userId);
      allow create, update: if isAdmin() || (isOwner(userId) && request.resource.data.role == 'student');
      allow delete: if isAdmin();
    }
    match /students/{studentId} {
      allow read: if isAdmin() || (
        isAuthenticated() && (
          resource.data.authUid == request.auth.uid ||
          resource.data.email == request.auth.token.email
        )
      );
      allow write: if isAdmin();
    }
    match /attendance/{recordId} {
      allow read: if isAdmin() || (
        isAuthenticated() && (
          resource.data.authUid == request.auth.uid ||
          (exists(/databases/$(database)/documents/users/$(request.auth.uid)) &&
           get(/databases/$(database)/documents/users/$(request.auth.uid)).data.rfidUID == resource.data.rfidUID)
        )
      );
      allow write: if isAdmin();
    }
  }
}
